SELECT json_build_object('connections', (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'client backend'), 'queries', (SELECT COALESCE(sum(xact_commit + xact_rollback), 0) FROM pg_stat_database), 'dataMb', (SELECT round(COALESCE(sum(pg_database_size(datname)), 0) / 1048576) FROM pg_database));
